    <div className="p-0">
      {handleBack && <FilterHeader label={filter.label} onBack={handleBack} />}
      <DepartmentFilterDropdown
        selectedOrgs={selectedOrgs}
        onOrgsChange={(orgs) => {
          onFilterChange(filter.key, orgs);
        }}
        facilityId={facilityId}
        handleBack={handleBack}
      />
    </div>
  );
}

